/// Weight functions required by prediction-collateral calls.
/// Prediction-collateral 调用所需的权重函数。
pub trait WeightInfo {
    fn deposit() -> Weight;
    fn withdraw() -> Weight;
    fn set_asset_whitelisted() -> Weight;
    fn set_asset_deposit_paused() -> Weight;
    fn set_global_deposit_paused() -> Weight;
}

/// Nexus benchmark-generated database-weight adapter.
/// Nexus benchmark 生成的数据库权重适配器。
pub struct SubstrateWeight<T>(PhantomData<T>);

impl<T: frame_system::Config> WeightInfo for SubstrateWeight<T> {
    fn deposit() -> Weight {
        Weight::from_parts(271_665_000, 7_144)
            .saturating_add(T::DbWeight::get().reads_writes(10, 6))
    }

    fn withdraw() -> Weight {
        Weight::from_parts(259_036_000, 7_053).saturating_add(T::DbWeight::get().reads_writes(6, 6))
    }

    fn set_asset_whitelisted() -> Weight {
        Weight::from_parts(50_675_000, 3_916).saturating_add(T::DbWeight::get().reads_writes(1, 1))
    }

    fn set_asset_deposit_paused() -> Weight {
        Weight::from_parts(26_529_000, 0).saturating_add(T::DbWeight::get().writes(1))
    }

    fn set_global_deposit_paused() -> Weight {
        Weight::from_parts(24_028_000, 0).saturating_add(T::DbWeight::get().writes(1))
    }
}

